using ForgeMission.Application.Host; using ForgeMission.Core.Resolution; using ForgeMission.Orchestration; using Microsoft.Extensions.Configuration;
namespace ForgeMission.Desktop.Maui;
public sealed class DesktopSession : IAsyncDisposable { private readonly CancellationTokenSource _stop=new(); private LocalApplicationHost? _host; public void Start(WebView view) { view.Source=new HtmlWebViewSource{Html="<h2 style='font-family:Segoe UI;text-align:center;margin-top:40vh'>Starting Forge…</h2>"}; _=Task.Run(async()=>{try { var c=new ConfigurationBuilder().AddEnvironmentVariables().Build(); var p=CredentialStore.GetPlatform(); if(p is null||string.IsNullOrEmpty(p.Key)) throw new InvalidOperationException("Not signed in. Run forge login, then retry."); var (mission,mode,launcher)=await MissionRuntimeResolver.ResolveAsync(c,_stop.Token); await using var conversation=await ConversationRuntimeBootstrap.PrepareAsync(c,_stop.Token); _host=await LocalApplicationHost.StartAsync(new(mission,mode,p.Key,conversation.BaseUrl,AppContext.BaseDirectory),_stop.Token); MainThread.BeginInvokeOnMainThread(()=>view.Source=new UrlWebViewSource{Url=_host.Url}); await Task.Delay(Timeout.Infinite,_stop.Token); if (launcher is not null) await launcher.DisposeAsync(); } catch(Exception ex) when(ex is not OperationCanceledException) { MainThread.BeginInvokeOnMainThread(()=>view.Source=new HtmlWebViewSource{Html=$"<h2>Forge could not start</h2><p>{System.Net.WebUtility.HtmlEncode(ex.Message)}</p>"}); }}); } public async ValueTask DisposeAsync(){_stop.Cancel(); if(_host is not null) await _host.DisposeAsync(); _stop.Dispose();} }
